function money(value) {
  return Number(value || 0).toLocaleString(undefined, { style: "currency", currency: "USD" });
}

function marketEstimateMoney(value) {
  const amount = Number(value || 0);
  if (!Number.isFinite(amount)) return money(0);
  if (amount !== 0 && Math.abs(amount) < 0.01) {
    return amount.toLocaleString(undefined, {
      style: "currency",
      currency: "USD",
      minimumFractionDigits: 2,
      maximumFractionDigits: 6,
    });
  }
  return money(amount);
}

function minutes(seconds) {
  return Math.floor((seconds || 0) / 60);
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

async function loadLegalDocument(force = false) {
  if (state.legalDocument && !force) return state.legalDocument;
  state.legalDocument = await api("/api/legal/current", { timeoutMs: 12000 });
  return state.legalDocument;
}

function legalDocumentView(documentData) {
  const documentText = String(documentData?.document || "").trim();
  return `<div class="legal-document" data-legal-scroll tabindex="0" aria-label="Full legal agreement">${documentText ? escapeHtml(documentText) : "The legal document could not be loaded."}</div>`;
}

function renderLegalPortal(documentData, { blocking = false, loading = false, error = "" } = {}) {
  if (!legalPortal) return;
  const signedIn = Boolean(state.session?.user);
  const acceptanceRequired = signedIn && state.session?.legal?.required && !state.session?.legal?.accepted;
  const mustAccept = blocking || acceptanceRequired;
  legalPortal.dataset.blocking = mustAccept ? "true" : "false";
  legalPortal.innerHTML = `<div class="legal-gate-backdrop ${mustAccept ? "required" : "viewer"}">
    <section class="legal-gate" role="dialog" aria-modal="true" aria-labelledby="legalGateTitle">
      <header><div class="legal-seal">TL</div><div><span>THUNDERLINK CAD SYSTEM</span><h1 id="legalGateTitle">${mustAccept ? "Review required before continuing" : "EULA, Terms & Privacy"}</h1><p>Version ${escapeHtml(documentData?.current_version || "1.0")} · Effective ${escapeHtml(documentData?.effective_date || "August 8, 2026")}</p></div>${mustAccept ? `<strong>REQUIRED</strong>` : `<button type="button" data-legal-close aria-label="Close legal document">×</button>`}</header>
      ${loading ? `<div class="legal-loading"><i></i><span>Loading the controlled agreement…</span></div>` : error ? `<div class="legal-error"><strong>Agreement unavailable</strong><p>${escapeHtml(error)}</p></div>` : legalDocumentView(documentData)}
      <footer>
        <div><strong>${mustAccept ? "Scroll through the complete agreement to unlock acceptance." : "Controlled document"}</strong><small>${mustAccept ? "Accepting records the document version, timestamp, and account." : `SHA-256 ${escapeHtml(String(documentData?.document_sha256 || "").slice(0, 18))}…`}</small></div>
        <div class="legal-actions">
          ${mustAccept ? `<button type="button" class="secondary" data-legal-logout>Log out</button><button type="button" class="primary" data-legal-accept disabled>Accept and continue</button>` : `<button type="button" class="primary" data-legal-close>Done</button>`}
        </div>
      </footer>
    </section>
  </div>`;
  bindLegalPortal(documentData, mustAccept, loading || Boolean(error));
}

function bindLegalPortal(documentData, mustAccept, unavailable = false) {
  if (!legalPortal) return;
  $$('[data-legal-close]', legalPortal).forEach(button => button.addEventListener('click', () => {
    if (legalPortal.dataset.blocking === "true") return;
    legalPortal.innerHTML = "";
  }));
  const scroll = $('[data-legal-scroll]', legalPortal);
  const acceptButton = $('[data-legal-accept]', legalPortal);
  if (scroll && acceptButton && !unavailable) {
    const updateReadState = () => {
      const complete = scroll.scrollTop + scroll.clientHeight >= scroll.scrollHeight - 18;
      acceptButton.disabled = !complete;
      acceptButton.classList.toggle("ready", complete);
    };
    scroll.addEventListener('scroll', updateReadState, { passive: true });
    requestAnimationFrame(updateReadState);
  }
  acceptButton?.addEventListener('click', async () => {
    if (acceptButton.disabled) return;
    acceptButton.disabled = true;
    acceptButton.textContent = "Recording acceptance…";
    try {
      const result = await api('/api/legal/accept', {
        method: 'POST',
        confirm: false,
        body: { policy_version: documentData.current_version, accepted: true, read_confirmed: true },
      });
      if (state.session) state.session.legal = result.legal;
      legalPortal.innerHTML = "";
      await loadSession();
      toast("Agreement accepted");
    } catch (error) {
      acceptButton.disabled = false;
      acceptButton.textContent = "Accept and continue";
      toast(error.message);
    }
  });
  $('[data-legal-logout]', legalPortal)?.addEventListener('click', async () => {
    try { await api('/api/auth/logout', { method: 'POST', confirm: false }); } catch {}
    stopSessionRefresh();
    state.session = null;
    state.activeApp = null;
    legalPortal.innerHTML = "";
    render();
  });
}

async function openLegalPortal({ blocking = false } = {}) {
  renderLegalPortal(state.legalDocument || state.session?.legal || {}, { blocking, loading: !state.legalDocument });
  try {
    const documentData = await loadLegalDocument();
    renderLegalPortal(documentData, { blocking });
  } catch (error) {
    renderLegalPortal(state.session?.legal || {}, { blocking, error: error.message || "Unable to load the agreement." });
  }
}

async function syncLegalGate() {
  const legal = state.session?.legal;
  if (state.session?.user && legal?.required && !legal?.accepted) {
    state.activeApp = null;
    await openLegalPortal({ blocking: true });
    return;
  }
  if (legalPortal?.dataset.blocking === "true") legalPortal.innerHTML = "";
}

function selectedAttr(value, current) {
  return String(value) === String(current) ? " selected" : "";
}

function renderOptions(options, current) {
  return options.map((option) => `<option value="${escapeHtml(option)}"${selectedAttr(option, current)}>${escapeHtml(option)}</option>`).join("");
}

function toast(message) {
  if (!message) return;
  toastEl.textContent = message;
  toastEl.classList.add("show");
  clearTimeout(toastEl.timer);
  toastEl.timer = setTimeout(() => toastEl.classList.remove("show"), 2600);
}

function isMutationMethod(method) {
  return ["POST", "PATCH", "PUT", "DELETE"].includes(String(method || "GET").toUpperCase());
}

function actionConfirmExempt(path) {
  const cleanPath = String(path || "").split("?")[0];
  return cleanPath === "/api/presence" || cleanPath === "/api/auth/login" || cleanPath === "/api/auth/logout" || cleanPath === "/api/auth/register" || cleanPath === "/api/legal/accept";
}

function actionFingerprint(method, path, body = "") {
  const source = `${method}|${path}|${body}`;
  let hash = 2166136261;
  for (let index = 0; index < source.length; index += 1) {
    hash ^= source.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  const hex = (hash >>> 0).toString(16).toUpperCase().padStart(8, "0");
  return `DF-${hex.slice(0, 4)}-${hex.slice(4, 8)}`;
}

function actionTitleFromPath(path, method) {
  const clean = String(path || "")
    .split("?")[0]
    .replace(/^\/api\//, "")
    .replaceAll("/", " ")
    .replaceAll("-", " ")
    .replace(/\b\d+\b/g, "record");
  const title = clean.replace(/\b\w/g, (char) => char.toUpperCase()).trim() || "System Action";
  return `${method} ${title}`;
}

function confirmDigitalAction({ method, path, body }) {
  if (activeActionConfirm) {
    toast("Confirm the open action first");
    return Promise.resolve(false);
  }
  activeActionConfirm = true;
  const signature = actionFingerprint(method, path, body);
  const title = actionTitleFromPath(path, method);
  return new Promise((resolve) => {
    const backdrop = document.createElement("div");
    backdrop.className = "action-confirm-backdrop";
    backdrop.innerHTML = `
      <section class="action-confirm-modal" role="dialog" aria-modal="true" aria-label="Confirm request">
        <div>
          <p class="eyebrow">Confirm request</p>
          <h2>${escapeHtml(title)}</h2>
          <p>This will send one request to the RP system. Confirm once and wait for the response before tapping again.</p>
        </div>
        <div class="digital-signature">
          <span>Digital footprint</span>
          <strong>${escapeHtml(signature)}</strong>
        </div>
        <div class="action-confirm-actions">
          <button class="secondary" type="button" data-action-confirm-cancel>Cancel</button>
          <button class="primary" type="button" data-action-confirm-ok>Confirm send</button>
        </div>
      </section>
    `;
    const cleanup = (value) => {
      activeActionConfirm = false;
      backdrop.remove();
      resolve(value);
    };
    backdrop.addEventListener("click", (event) => {
      if (event.target === backdrop) cleanup(false);
    });
    backdrop.querySelector("[data-action-confirm-cancel]")?.addEventListener("click", () => cleanup(false));
    backdrop.querySelector("[data-action-confirm-ok]")?.addEventListener("click", () => cleanup(true));
    document.body.appendChild(backdrop);
    backdrop.querySelector("[data-action-confirm-ok]")?.focus();
  });
}

async function copyToClipboard(value) {
  const text = String(value || "");
  if (!text) return false;
  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(text);
    return true;
  }
  const area = document.createElement("textarea");
  area.value = text;
  area.setAttribute("readonly", "");
  area.style.position = "fixed";
  area.style.opacity = "0";
  document.body.appendChild(area);
  area.select();
  const copied = document.execCommand("copy");
  area.remove();
  return copied;
}

async function api(path, options = {}) {
  const timeoutMs = options.timeoutMs ?? 0;
  const confirmOption = options.confirm;
  const { timeoutMs: _timeoutMs, confirm: _confirm, headers: optionHeaders, ...restOptions } = options;
  const requestInit = {
    credentials: "same-origin",
    headers: { "Content-Type": "application/json", ...(optionHeaders || {}) },
    ...restOptions,
  };
  requestInit.method = String(requestInit.method || "GET").toUpperCase();
  if (requestInit.body && typeof requestInit.body !== "string") {
    requestInit.body = JSON.stringify(requestInit.body);
  }
  const mutation = isMutationMethod(requestInit.method);
  const lockKey = mutation ? `${requestInit.method} ${path} ${requestInit.body || ""}` : "";
  if (lockKey && pendingMutations.has(lockKey)) {
    toast("Action already sending");
    return pendingMutations.get(lockKey);
  }
  if (mutation && confirmOption !== false && !actionConfirmExempt(path)) {
    const confirmed = await confirmDigitalAction({ method: requestInit.method, path, body: requestInit.body || "" });
    if (!confirmed) throw new Error("");
  }
  let timeoutId = null;
  let controller = null;
  if (timeoutMs > 0) {
    controller = new AbortController();
    requestInit.signal = controller.signal;
    timeoutId = setTimeout(() => {
      controller.abort("Request timed out");
    }, timeoutMs);
  }
  const request = (async () => {
    try {
      const response = await fetch(path, {
        ...requestInit,
      });
      clearTimeout(timeoutId);
      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.error || "Request failed");
      }
      return data;
    } finally {
      clearTimeout(timeoutId);
      if (lockKey) pendingMutations.delete(lockKey);
    }
  })();
  if (lockKey) pendingMutations.set(lockKey, request);
  return request;
}

function antiCheatLockToken(session) {
  const lock = session?.anti_cheat_lock;
  return lock ? `${lock.id || ""}:${lock.player_uid || ""}:${lock.grey_screened_at || ""}` : "";
}

function marketBankruptcyNoticeToken(session) {
  const notice = session?.market_bankruptcy_notice;
  return notice ? `${notice.id || ""}:${notice.created_at || ""}:${notice.claim?.status || ""}` : "";
}

function fecClearanceNoticeToken(session) {
  const notice = session?.fec_clearance_notice;
  return notice ? `${notice.id || ""}:${notice.created_at || ""}:${notice.amount || ""}` : "";
}

function startSessionRefresh() {
  if (sessionRefreshTimer) return;
  sessionRefreshTimer = window.setInterval(refreshSessionInBackground, SESSION_REFRESH_MS);
}

function stopSessionRefresh() {
  if (!sessionRefreshTimer) return;
  window.clearInterval(sessionRefreshTimer);
  sessionRefreshTimer = null;
}

async function refreshSessionInBackground() {
  if (sessionRefreshInFlight || !state.session?.user) return;
  sessionRefreshInFlight = true;
  try {
    const previousLock = antiCheatLockToken(state.session);
    const previousBankruptcyNotice = marketBankruptcyNoticeToken(state.session);
    const previousFecClearanceNotice = fecClearanceNoticeToken(state.session);
    const previousUnread = Number(state.session?.unread_messages || 0);
    const nextSession = await api("/api/session", { timeoutMs: 8000 });
    const nextLock = antiCheatLockToken(nextSession);
    const nextBankruptcyNotice = marketBankruptcyNoticeToken(nextSession);
    const nextFecClearanceNotice = fecClearanceNoticeToken(nextSession);
    state.session = nextSession;
    if (!nextSession?.user) {
      stopSessionRefresh();
      state.activeApp = null;
      if (legalPortal) legalPortal.innerHTML = "";
      render();
      return;
    }
    if (nextSession?.legal?.required && !nextSession?.legal?.accepted) {
      state.activeApp = null;
      render();
      await syncLegalGate();
      return;
    }
    if (nextLock !== previousLock) {
      if (nextLock) {
        state.activeApp = null;
        toast("Faircroft profile locked by Anti-Cheat");
      } else {
        toast("Anti-Cheat profile lock removed");
      }
      render();
      return;
    }
    if (nextBankruptcyNotice !== previousBankruptcyNotice || nextFecClearanceNotice !== previousFecClearanceNotice) {
      render();
      return;
    }
    if (Number(nextSession?.unread_messages || 0) !== previousUnread && (!state.activeApp || state.activeApp === "messages")) {
      render();
    }
  } catch (error) {
    console.warn("Session refresh failed", error);
  } finally {
    sessionRefreshInFlight = false;
  }
}

async function loadSession() {
  state.session = await api("/api/session", { timeoutMs: SESSION_BOOT_TIMEOUT_MS });
  if (state.session?.user) startSessionRefresh();
  else stopSessionRefresh();
  if (state.session?.user && state.session?.legal?.required && !state.session?.legal?.accepted) {
    state.activeApp = null;
    render();
    await syncLegalGate();
    return;
  }
  if (state.session?.user && (state.pendingArmaCode || state.armaLinkDeepLink) && !state.activeApp) {
    state.activeApp = "profile";
    state.profileView = "connections";
    await loadAppData("profile");
  }
  render();
  await syncLegalGate();
}

function renderBootScreen() {
  const connecting = state.boot.status === "connecting";
  const attempting = state.boot.attempt || 1;
  return phone(`
    <section class="boot-screen ${connecting ? "booting" : ""}">
      <video class="faircroft-entrance-media" autoplay muted loop playsinline poster="/static/brand/faircroft-emblem.webp">
        <source src="/static/brand/faircroft-light-sweep.mp4" type="video/mp4" />
      </video>
      <div class="boot-orb" aria-hidden="true">
        <span class="boot-orb-core"></span>
        <span class="boot-orb-ring"></span>
        <span class="boot-orb-ring"></span>
      </div>
      <p class="boot-title">${connecting ? "Entering Faircroft..." : "Cannot contact Faircroft services"}</p>
      <p class="boot-subtitle">
        ${connecting ? "Syncing your account and loading modules. This usually takes just a second." : escapeHtml(state.boot.lastError || "Server response could not be loaded right now.")}
      </p>
      <div class="boot-progress">
        <span></span>
      </div>
      <p class="boot-meta">Connection attempt ${attempting} - RP OS ${OS_VERSION}</p>
      ${connecting ? `<p class="boot-note">If this persists, check your API host and network connection, then retry.</p>` : `<button class="primary" data-retry-boot>Retry</button>`}
      ${state.boot.lastError ? `<p class="boot-error">${escapeHtml(state.boot.lastError)}</p>` : ""}
    </section>
  `);
}

function bindBoot() {
  if (state.boot.status === "connected") return;
  $$("[data-retry-boot]").forEach((button) => {
    button.addEventListener("click", () => bootApp());
  });
}

async function bootApp() {
  state.boot.attempt += 1;
  state.boot.status = "connecting";
  state.boot.lastError = "";
  app.innerHTML = renderBootScreen();
  bindBoot();
  try {
    await loadSession();
    state.boot.status = "connected";
  } catch (error) {
    state.boot.status = "failed";
    state.boot.lastError = error.name === "AbortError" ? `Session request timed out after ${Math.round(SESSION_BOOT_TIMEOUT_MS / 1000)} seconds.` : error.message || "Unable to reach the API.";
    app.innerHTML = renderBootScreen();
    bindBoot();
  }
}

