function isScopedFecInvestigator() {
  return can("fec_investigator") && !canAny("owner", "dev");
}

function devToolsSectionName(section = state.devTab) {
  if (isScopedFecInvestigator()) return "fec-investigations";
  return section === "property-intelligence" ? "housing-market" : section;
}

function devToolsSectionUrl(section = state.devTab) {
  const normalized = devToolsSectionName(section);
  const params = new URLSearchParams({ section: normalized });
  if (normalized === "banking-settings") {
    params.set("page", String(state.devBankCommandPage || 1));
    params.set("status", String(state.devBankCommandStatus || "all"));
  }
  if (normalized === "audit") params.set("page", String(state.devAuditPage || 1));
  return `/api/dev-tools?${params.toString()}`;
}

async function loadDevToolsSection(section = state.devTab, { force = false } = {}) {
  const normalized = devToolsSectionName(section);
  const ttl = DEV_TOOLS_REFRESH_MS[normalized] || 300000;
  const loadedAt = Number(state.devSectionLoadedAt[normalized] || 0);
  if (!force && loadedAt && Date.now() - loadedAt < ttl) return state.cache["dev-tools"] || {};

  const url = devToolsSectionUrl(normalized);
  if (!devToolsSectionRequests.has(url)) {
    const request = api(url).then((data) => {
      state.cache["dev-tools"] = { ...(state.cache["dev-tools"] || {}), ...data };
      state.devSectionLoadedAt[normalized] = Date.now();
      return state.cache["dev-tools"];
    }).finally(() => devToolsSectionRequests.delete(url));
    devToolsSectionRequests.set(url, request);
  }
  return devToolsSectionRequests.get(url);
}

function stopDevToolsRefresh() {
  if (devToolsRefreshTimer) clearInterval(devToolsRefreshTimer);
  devToolsRefreshTimer = null;
}

function devToolsFormIsActive() {
  const active = document.activeElement;
  return Boolean(active?.closest?.(".dev-workspace") && (
    active.matches("input, select, textarea") || active.isContentEditable
  ));
}

function scheduleDevToolsRefresh() {
  stopDevToolsRefresh();
  if (state.activeApp !== "dev-tools") return;
  const section = devToolsSectionName();
  const interval = DEV_TOOLS_REFRESH_MS[section];
  if (!interval) return;
  devToolsRefreshTimer = setInterval(async () => {
    if (document.hidden || state.activeApp !== "dev-tools" || devToolsFormIsActive()) return;
    try {
      await refreshDevTools({ force: true, silent: true });
    } catch (error) {
      console.warn("Admin Tools background refresh deferred", error);
    }
  }, interval);
}

function wallstreetDataPath() {
  const ticker = String(state.marketTicker || "").trim().toUpperCase();
  const range = ["LIVE", "15M", "1H", "1D", "1W", "1M", "1Y"].includes(state.marketRange) ? state.marketRange : "LIVE";
  const params = new URLSearchParams({range});
  if (ticker) params.set("ticker", ticker);
  return `/api/wallstreet?${params.toString()}`;
}

async function fetchWallstreetData() {
  const path = wallstreetDataPath();
  if (marketDataRequest) {
    if (marketDataRequestPath === path) return marketDataRequest;
    try { await marketDataRequest; } catch (_) { /* The new selection still gets its own request. */ }
  }
  const request = api(path);
  marketDataRequest = request;
  marketDataRequestPath = path;
  try {
    return await request;
  } finally {
    if (marketDataRequest === request) {
      marketDataRequest = null;
      marketDataRequestPath = "";
    }
  }
}

async function loadAppData(id) {
  const loaders = {
    profile: () => api("/api/profile"),
    dmv: () => api("/api/dmv/me"),
    jobs: () => api("/api/jobs"),
    "my-faircroft": () => api("/api/my-faircroft"),
    fnn: () => api("/api/fnn"),
    court: () => api(can("judge") || can("owner") ? "/api/court/cases" : "/api/court/my-cases"),
    properties: () => api("/api/properties"),
    bank: () => api("/api/bank"),
    wallstreet: () => fetchWallstreetData(),
    lottery: () => api("/api/lottery"),
    sportsbook: () => api("/api/sportsbook"),
    casino: () => api("/api/casino"),
    treasury: () => api("/api/treasury"),
    business: () => api("/api/business"),
    messages: () => api("/api/messages"),
    contracts: () => api("/api/contracts"),
    changelog: () => api("/api/changelog"),
    roadmap: () => api("/api/roadmap"),
    mdt: async () => {
      const data = {
        charges: await api("/api/mdt/charges"),
        alerts: await api("/api/mdt/alerts"),
        reports: await api("/api/mdt/reports"),
        bookings: await optionalApi("/api/mdt/bookings", { active: [], recent: [], stats: { active: 0, today: 0, released: 0 } }),
        bolos: await optionalApi("/api/mdt/bolos", { active: [], recent: [] }),
        cid: mdtCommandEnabled() ? await api("/api/cid/overview") : null,
        search: state.cache.mdt?.search || []
      };
      if (data.cid && state.mdtTab === "search" && !data.search.length) {
        state.mdtTab = "cid-command";
      }
      return data;
    },
    fire: () => api("/api/fire/overview"),
    "fire-settings": () => api("/api/fire/overview"),
    system: () => api("/api/system/settings"),
    "indeed-admin": () => api("/api/indeed-admin/applications"),
    "dev-tools": () => loadDevToolsSection(state.devTab),
    "beta-tasks": () => api("/api/beta/tasks"),
    downloads: () => api("/api/downloads/access"),
    leaderboards: () => api("/api/leaderboards"),
    stats: () => api("/api/stats"),
    press: () => api("/api/press/reports"),
    citizenship: () => api("/api/citizenship"),
    "ice-mdt": () => api("/api/ice/overview"),
    insurance: () => api("/api/insurance"),
    gangs: () => api("/api/gangs"),
    realty: () => api("/api/realty"),
    "realty-dashboard": () => api("/api/realty-dashboard"),
    admin: async () => ({
      overview: await api("/api/admin/overview"),
      users: await api("/api/admin/users"),
    }),
  };
  if (loaders[id]) {
    try {
      state.cache[id] = await loaders[id]();
      if (id === "dev-tools" && state.activeApp === "dev-tools") scheduleDevToolsRefresh();
    } catch (error) {
      toast(error.message);
    }
  }
}

function renderRestrictionNotice() {
  const sanction = state.session?.admin_restriction || state.session?.sanction || {};
  const isAdminRestriction = Boolean(state.session?.admin_restriction);
  const expires = sanction.expires_at ? new Date(sanction.expires_at) : null;
  const expiryText = expires && !Number.isNaN(expires.getTime()) ? expires.toLocaleString() : "Pending staff review";
  const bail = Number(sanction.bail_amount || 0);
  return `
    <div class="stack restriction-notice">
      <section class="profile-hero restriction-hero">
        <div>
          <p class="eyebrow">${isAdminRestriction ? "Faircroft administrative action" : "Temporary account restriction"}</p>
          <h3>${isAdminRestriction ? "CAD Access Locked" : "Limited Access Active"}</h3>
          <p>${isAdminRestriction ? "Your linked Arma account is unchanged. Admin Chat and this notice remain available." : "Your account remains available for Profile, Bank, and this notice."}</p>
        </div>
        <span class="pill amber">${escapeHtml(humanLabel(String(sanction.type || "timeout").replace("cad_", "")))}</span>
      </section>
      <section class="profile-link-card">
        <div class="restriction-detail"><span>Reason</span><strong>${escapeHtml(sanction.reason || "No public reason supplied")}</strong></div>
        <div class="restriction-detail"><span>Report</span><strong>${escapeHtml(sanction.report_number || "Not available")}</strong></div>
        <div class="restriction-detail"><span>Restriction ends</span><strong>${escapeHtml(expiryText)}</strong></div>
        ${isAdminRestriction ? "" : `<div class="restriction-detail"><span>Bail amount</span><strong>${bail > 0 ? money(bail) : "No bail set"}</strong></div>`}
      </section>
      <section class="profile-link-card">
        <h3>${isAdminRestriction ? "Contact administration" : "How access is restored"}</h3>
        <p>${isAdminRestriction ? "Open Admin Chat to speak directly with Faircroft staff about this action." : (bail > 0 ? `A friend may arrange payment of ${money(bail)} with Faircroft staff on your behalf. Staff must confirm payment and release the restriction.` : "No bail amount was assigned. You must serve the timeout or contact staff if you believe it was issued incorrectly.")}</p>
        <p class="muted small">${isAdminRestriction ? "Timed actions expire automatically. Permanent actions require administrative review." : "Otherwise, serve the full timeout. Access returns automatically after the listed expiration time."}</p>
      </section>
    </div>`;
}

