  const dropMarker = largestDrop.point && largestDrop.pct < 0 ? `<g class="market-v14-move-marker drop"><circle cx="${largestDrop.point.x}" cy="${largestDrop.point.y}" r="5"/></g>` : "";
  const lastRecordedAt = history.at(-1)?.time || now;
