function renderAdminMarkets(markets) {
  return `<div class="list">${markets.map((market) => `
    <article class="card">
      <form class="admin-market-form form-grid" data-market="${escapeHtml(market.market)}">
        <div class="row"><h3>${escapeHtml(market.market)}</h3><span class="pill">${market.max_slots} slots</span></div>
        <label>Market job cap<input name="max_slots" type="number" value="${escapeHtml(market.max_slots)}" /></label>
        <button class="primary" type="submit">Save cap</button>
      </form>
    </article>
  `).join("")}</div>`;
}

function bindSystem() {
  $("#systemSettingsForm")?.addEventListener("submit", async (event) => {
    event.preventDefault();
    const form = event.currentTarget;
    const formData = new FormData(form);
    const body = {};
    if (form.elements.namedItem("autopilot_verify_enabled")) {
      body.autopilot_verify_enabled = formData.get("autopilot_verify_enabled") === "on";
      body.autopilot_verify_minutes = formData.get("autopilot_verify_minutes");
    }
    if (form.elements.namedItem("update_lockdown_enabled")) {
      body.update_lockdown_enabled = formData.get("update_lockdown_enabled") === "on";
      body.update_lockdown_title = formData.get("update_lockdown_title");
      body.update_lockdown_message = formData.get("update_lockdown_message");
      body.update_lockdown_eta = formData.get("update_lockdown_eta");
    }
    try {
      await api("/api/system/settings", {
        method: "PATCH",
        body,
      });
      toast("System settings saved");
      if (state.activeApp === "dev-tools") await refreshDevTools({ force: true });
      else await loadAppData("system");
      await loadSession();
    } catch (error) {
      toast(error.message);
    }
  });
}

function bindIndeedAdmin() {
  $$("[data-indeed-application-filter]").forEach((button) => button.addEventListener("click", () => {
    state.indeedApplicationFilter = button.dataset.indeedApplicationFilter;
    render();
  }));
  $$("[data-indeed-application-status]").forEach((button) => button.addEventListener("click", async () => {
    const form = button.closest(".indeed-application-review-form");
    if (!form) return;
    try {
      await api(`/api/indeed-admin/applications/${form.dataset.applicationId}`, {
        method: "PATCH",
        body: {
          status: button.dataset.indeedApplicationStatus,
          reviewer_notes: new FormData(form).get("reviewer_notes") || "",
        },
      });
      toast("Application updated");
      await loadAppData("indeed-admin");
      await loadSession();
      render();
    } catch (error) {
      toast(error.message);
    }
  }));
}

function applyAdminUserSearch() {
  const query = String(state.adminSearch || "").trim().toLowerCase();
  const cards = $$("[data-admin-user-card]");
  let visible = 0;
  cards.forEach((card) => {
    const match = !query || String(card.dataset.adminSearch || "").includes(query);
    card.classList.toggle("search-hidden", !match);
    if (match) visible += 1;
  });
  const count = $("[data-admin-search-count]");
  if (count) count.textContent = `${visible} of ${cards.length} accounts`;
  const empty = $("[data-admin-search-empty]");
  empty?.classList.toggle("search-hidden", visible > 0);
  $("[data-clear-admin-search]")?.toggleAttribute("disabled", !query);
}

function bindAdmin() {
  const accountWorkspace = state.activeApp === "dev-tools" ? "dev-tools" : "admin";
  const refreshAccountWorkspace = () => loadAppData(accountWorkspace);
  const searchInput = $("[data-admin-account-search]");
  searchInput?.addEventListener("input", (event) => {
    state.adminSearch = event.currentTarget.value;
    applyAdminUserSearch();
  });
  $("[data-clear-admin-search]")?.addEventListener("click", () => {
    state.adminSearch = "";
    if (searchInput) {
      searchInput.value = "";
      searchInput.focus();
    }
    applyAdminUserSearch();
  });
  $$(".referral-deposit-form").forEach((form) => form.addEventListener("submit", async (event) => {
    event.preventDefault();
    try {
      await api(`/api/admin/referrals/${form.dataset.referralId}/deposit`, {
        method: "POST",
        body: Object.fromEntries(new FormData(form).entries()),
      });
      toast("Referral cash deposited");
      await loadAppData("admin");
      await loadSession();
      render();
    } catch (error) {
      toast(error.message);
    }
  }));
  $$("[data-admin-tab]").forEach((button) => button.addEventListener("click", () => {
    state.adminTab = button.dataset.adminTab;
    state.adminAccountId = null;
    render();
  }));
  $$("[data-admin-application-filter]").forEach((button) => button.addEventListener("click", () => {
    state.adminApplicationFilter = button.dataset.adminApplicationFilter;
    render();
  }));
  $$("[data-admin-application-status]").forEach((button) => button.addEventListener("click", async () => {
    const form = button.closest(".admin-application-review-form");
    if (!form) return;
    try {
      await api(`/api/admin/department-applications/${form.dataset.applicationId}`, {
        method: "PATCH",
        body: {
          status: button.dataset.adminApplicationStatus,
          reviewer_notes: new FormData(form).get("reviewer_notes") || "",
        },
      });
      toast("Application updated");
      await loadAppData("admin");
      await loadSession();
      render();
    } catch (error) {
      toast(error.message);
    }
  }));
  $$("[data-open-admin-account]").forEach((button) => button.addEventListener("click", () => {
    state.adminAccountId = button.dataset.openAdminAccount;
    state.adminAccountSection = "account";
    render();
  }));
  $$("[data-admin-account-section]").forEach((button) => button.addEventListener("click", () => {
    state.adminAccountSection = button.dataset.adminAccountSection;
    render();
  }));
  $$("[data-close-admin-account]").forEach((button) => button.addEventListener("click", (event) => {
    if (event.currentTarget.classList?.contains("modal-backdrop") && event.target !== event.currentTarget) return;
    state.adminAccountId = null;
    render();
  }));
  $$(".admin-user-form").forEach((form) => form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const formData = new FormData(form);
    const roles = formData.getAll("roles");
    try {
      await api(`/api/admin/users/${form.dataset.userId}`, {
        method: "PATCH",
        body: {
          verified: formData.get("verified") === "on",
          primary_agency: formData.get("primary_agency"),
          roles,
          unlock_name_changes: formData.get("unlock_name_changes") === "on",
        },
      });
      toast("User saved");
      await refreshAccountWorkspace();
      await loadSession();
    } catch (error) {
      toast(error.message);
    }
  }));
  $$(".admin-password-form").forEach((form) => form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const formData = new FormData(form);
    const password = String(formData.get("password") || "");
    const confirmPassword = String(formData.get("confirm_password") || "");
    if (password !== confirmPassword) {
      toast("Passwords do not match");
      return;
    }
    try {
      await api(`/api/admin/users/${form.dataset.userId}`, {
        method: "PATCH",
        body: { password },
      });
      form.reset();
      toast("Password reset");
      await refreshAccountWorkspace();
      render();
    } catch (error) {
      toast(error.message);
    }
  }));
  $$(".dev-email-reset-form").forEach((form) => form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const formData = new FormData(form);
    const email = String(formData.get("email") || "").trim().toLowerCase();
    const confirmation = String(formData.get("confirm_email") || "").trim().toLowerCase();
    if (email !== confirmation) {
      toast("Email addresses do not match");
      return;
    }
    if (!window.confirm(`Reset this account's sign-in email to ${email}?`)) return;
    try {
      await api(`/api/dev-tools/accounts/${form.dataset.userId}/email`, { method: "PATCH", body: { email } });
      toast("Account email reset and audit entry recorded");
      await refreshAccountWorkspace();
      await loadSession();
      render();
    } catch (error) {
      toast(error.message);
    }
  }));
  $$(".admin-enforcement-form").forEach((form) => form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const formData = new FormData(form, event.submitter);
    const action = String(formData.get("action") || "");
    const label = humanLabel(action.replace("cad_", "").replace("arma_", ""));
    const destination = action.startsWith("arma_") ? "Arma server" : "RP OS/CAD";
    if (!confirm(`Apply ${label} to ${destination} for this account?`)) return;
    try {
      const result = await api(`/api/admin/users/${form.dataset.userId}/enforcement`, {
        method: "POST",
        body: Object.fromEntries(formData.entries()),
      });
      toast(`${label} applied · ${result.report_number}`);
      await refreshAccountWorkspace();
      await loadSession();
      render();
    } catch (error) {
      toast(error.message);
    }
  }));
  $$(".admin-job-form").forEach((form) => form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const formData = new FormData(form);
    try {
      await api(`/api/admin/jobs/${form.dataset.jobId}`, {
        method: "PATCH",
        body: {
          rate_per_hour: formData.get("rate_per_hour"),
          max_positions: formData.get("max_positions"),
          required_minutes_daily: formData.get("required_minutes_daily"),
          requirement: formData.get("requirement"),
          active: formData.get("active") === "on",
        },
      });
      toast("Job saved");
      await loadAppData("admin");
      render();
    } catch (error) {
      toast(error.message);
    }
  }));
  $$(".admin-market-form").forEach((form) => form.addEventListener("submit", async (event) => {
    event.preventDefault();
    try {
      await api(`/api/admin/markets/${encodeURIComponent(form.dataset.market)}`, {
        method: "PATCH",
        body: Object.fromEntries(new FormData(form).entries()),
      });
      toast("Market cap saved");
      await loadAppData("admin");
      render();
    } catch (error) {
      toast(error.message);
    }
  }));
}

async function heartbeat() {
  if (!state.session?.user) return;
  try {
    await api("/api/presence", { method: "POST" });
  } catch {
    return;
  }
}

if ("serviceWorker" in navigator) {
  window.addEventListener("load", () => navigator.serviceWorker?.register("/service-worker.js?v=0.4.1-ravenhood-engine-v1").catch(() => {}));
}

legalFooterLink?.addEventListener("click", () => {
  const blocking = Boolean(state.session?.user && state.session?.legal?.required && !state.session?.legal?.accepted);
  openLegalPortal({ blocking });
});

window.addEventListener("beforeinstallprompt", (event) => {
  event.preventDefault();
  deferredPwaInstallPrompt = event;
  if (state.session?.user) render();
});

app.addEventListener("click", async (event) => {
  if (event.target.closest("[data-system-banner-dismiss]")) {
    state.systemBannerDismissed = true;
    render();
    return;
  }
  if (event.target.closest("[data-desktop-download]")) {
    let access;
    try {
      access = await api("/api/desktop/access");
    } catch (error) {
      window.alert(`${error.message || "You must be in the Faircroft Beta Program to download the desktop app."}\n\n:(`);
      return;
    }
    const confirmed = window.confirm(
      "Download the official Faircroft RP Windows installer?\n\nOfficial releases are scanned with Microsoft Defender and include a public SHA-256 checksum. Only install files downloaded from Faircroft or the official Faircroft GitHub release. Faircroft cannot accept responsibility for modified copies, unsupported computers, interrupted downloads, or incorrect installation.\n\nThe installer will show the complete safety notice before installation."
    );
    if (!confirmed) return;
    window.location.href = access.download_url;
    return;
  }
  const installButton = event.target.closest("[data-pwa-install]");
  if (installButton) {
    if (deferredPwaInstallPrompt) {
      deferredPwaInstallPrompt.prompt();
      const choice = await deferredPwaInstallPrompt.userChoice;
      if (choice.outcome === "accepted") {
        localStorage.setItem("faircroft.pwa.install.dismissed", "1");
      }
      deferredPwaInstallPrompt = null;
      render();
      return;
    }
    if (state.pwaInstallHelpOpen) {
      localStorage.setItem("faircroft.pwa.install.dismissed", "1");
      state.pwaInstallHelpOpen = false;
    } else {
      state.pwaInstallHelpOpen = true;
    }
    render();
    return;
  }
  if (event.target.closest("[data-pwa-install-dismiss]")) {
    localStorage.setItem("faircroft.pwa.install.dismissed", "1");
    state.pwaInstallHelpOpen = false;
    render();
  }
});

bootApp();

setInterval(heartbeat, 60_000);
setTimeout(heartbeat, 4_000);
